using Servicio.RetazoMarket.Business.DTOs.Pedido;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;public static class PedidoBusinessMapper {public static PedidoResponse ToResponse(PedidoDataModel m)=>new(){id_pedido=m.id_pedido,id_metodo=m.id_metodo,id_cliente=m.id_cliente,fecha_hora=m.fecha_hora,estado=m.estado,entrega_fisica=m.entrega_fisica,subtotal=m.subtotal,iva=m.iva,total=m.total,fecha_pago=m.fecha_pago,cliente_nombre=m.Cliente?.nombre,metodo_pago_nombre=m.MetodoPago?.met_nombre,detalles=m.Detalles.Select(d=>new DetallePedidoResponse{id_producto=d.id_producto,producto_nombre=d.Producto?.prod_nombre,cantidad=d.cantidad,precio_unitario=d.precio_unitario,porcentaje_descuento=d.porcentaje_descuento,monto_descuento=d.monto_descuento,subtotal_item=d.subtotal_item,personalizacion_selec=d.personalizacion_selec.Clone()}).ToList()};}
